const reduce=matchMedia('(prefers-reduced-motion: reduce)');let lenis;
function setupScroll(){if(lenis){lenis.destroy();lenis=undefined}if(!reduce.matches&&window.Lenis){lenis=new Lenis({duration:1.65,smoothWheel:true,wheelMultiplier:.72,touchMultiplier:1,anchors:{offset:-35},easing:t=>Math.min(1,1.001-Math.pow(2,-10*t))})}}setupScroll();reduce.addEventListener('change',setupScroll);
const words=document.querySelector('.word-reveal');words.innerHTML=words.textContent.split(' ').map(w=>`<span>${w}</span>`).join(' ');const wordSpans=[...words.children];
