const scenes={nocturne:{title:'Nocturne',description:'A fragrance story told through glass, shadow and the movement of liquid. An intimate product experience that reveals itself slowly.',interaction:'A bottle scene with scroll-driven camera movement and a liquid-inspired material treatment.',function:'Fragrance notes, collection details, product information and an enquiry flow.'},monolith:{title:'Monolith',description:'An architectural experience about the relationship between a building and its surroundings. Quiet typography gives space to light, material and proportion.',interaction:'A user-controlled sun that changes the light across a cliff-house scene.',function:'An architectural project gallery, individual project stories, studio information and a commission enquiry.'},aurel:{title:'Aurel Horologie',description:'Precision made visible. A watchmaker’s showcase that slows the visitor down to consider the mechanism behind a familiar object.',interaction:'A scroll-controlled exploded watch movement, revealing its parts one layer at a time.',function:'Collection pages, clear specifications, craft stories and product enquiries.'},velocity:{title:'Velocity Lab',description:'A performance-footwear launch built around energy and investigation. Motion introduces the product; technical views explain what makes it different.',interaction:'Interactive X-ray, thermal and CAD-inspired views of a shoe.',function:'Product details, colour selection, material information and a mobile-friendly product journey.'},nightshift:{title:'Nightshift Motor Co.',description:'An after-dark world for a custom motorcycle brand. Rain and controlled light frame the machine, while the story follows the craft behind the build.',interaction:'A press-and-hold engine-rev interaction, with optional sound and a visual alternative.',function:'Custom-build stories, motorcycle specifications and a commission enquiry.'}};
const tabs=[...document.querySelectorAll('[role=tab]')];function selectScene(button){tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===button));t.tabIndex=t===button?0:-1});const key=button.dataset.scene,p=scenes[key];document.querySelector('#experiment-art').dataset.scene=key;document.querySelector('#scene-count').textContent=String(tabs.indexOf(button)+1).padStart(2,'0')+' / 05';document.querySelector('#experiment-title').textContent=p.title;document.querySelector('#experiment-description').textContent=p.description;document.querySelector('#experiment-interaction').textContent=p.interaction;document.querySelector('#experiment-function').textContent=p.function;document.querySelector('#experiment-panel').setAttribute('aria-labelledby',button.id)}tabs.forEach((b,i)=>{b.onclick=()=>selectScene(b);b.onkeydown=e=>{let next;if(e.key==='ArrowRight'||e.key==='ArrowDown')next=(i+1)%tabs.length;if(e.key==='ArrowLeft'||e.key==='ArrowUp')next=(i-1+tabs.length)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();selectScene(tabs[next]);tabs[next].focus()}}});
